public void Update()
{
    float targetPosition = 10.0f;
    float currentValue = 0.0f;
    float smoothingValue = 0.1f;

    float delta = targetPosition - currentValue;
    delta *= smoothingValue;
    currentValue += delta;
}
```
This will move your `currentValue` towards `targetPosition` smoothly.

