        // Copy properties from old to new component
        newComponent.position = component.position;
        newComponent.rotation = component.rotation;
        newComponent.scale = component.scale;

        // Add new component to new DNA
        newDNA.components.Add(newComponent);
    }

    // Return new DNA
    return newDNA;
}
