    // Update method to handle reaction logic
    public void Update()
    {
        // Loop through all atoms
        foreach (Atom atom in atoms)
        {
            // Check for collisions with other atoms
            foreach (Atom other in atoms)
            {
                // Check if collision is valid (distance check)
                if (CheckCollision(atom, other))
                {
                    // Handle collision logic
                    HandleCollision(atom, other);
                }
            }
        }
    }

    // Check if two atoms are colliding
    private bool CheckCollision(Atom a, Atom b)
    {
        // Check distance between atoms
        if (MathHelper.Distance(a.x, a.y, a.z, b.x, b.y, b.z) < a.radius + b.radius)
        {
            return true;
        }
        return false;
    }

    // Handle collision logic
    private void HandleCollision(Atom a, Atom b)
    {
        // Update positions and child arrays
        a.children = CombineArrays(a.children, b.children);
        b.children = CombineArrays(b.children, a.children);
    }
}
